CREATE OR REPLACE VIEW public.cash_flow_detailed_view WITH (security_invoker = on) AS SELECT cash_flow_expenses.month, cash_flow_expenses.category_structure, max(cash_flow_expenses.category_description) AS category_description, 'despesa'::text AS source_type, sum(cash_flow_expenses.movement_value) AS total_value, count(*) AS transaction_count FROM cash_flow_expenses GROUP BY cash_flow_expenses.month, cash_flow_expenses.category_structure UNION ALL SELECT cash_flow_revenues.month, cash_flow_revenues.category_structure, max(cash_flow_revenues.category_description) AS category_description, 'receita'::text AS source_type, sum(cash_flow_revenues.movement_value) AS total_value, count(*) AS transaction_count FROM cash_flow_revenues GROUP BY cash_flow_revenues.month, cash_flow_revenues.category_structure;